-- =============================================================
-- SEED DATA: 2000 demo assets with maintenance / disposal / history
--
-- This script does NOT hardcode a database name - CI/Docker use
-- sj_gso_inventory while the app's own default (application.properties)
-- is gso_inventory. Select your target database on the command line
-- instead, e.g.:
--   mysql -u app -p sj_gso_inventory < seed_2000_assets.sql
--   docker exec -i sj_gso_db mysql -u app -papppassword sj_gso_inventory < seed_2000_assets.sql
--
-- All property numbers use the 'SEED-' prefix (not 'COA-') at first,
-- so the batch is trivially identifiable right after loading. Run
-- rename_seed_property_numbers.sql next to convert them to the app's
-- real 'COA-YEAR-###' format (it also snapshots the asset_ids into a
-- `seed_batch_assets` marker table first, so the batch stays fully
-- reversible afterward - see cleanup_seed_2000_assets.sql to remove it).
-- =============================================================

-- Categories (idempotent - safe to re-run)
ON DUPLICATE KEY UPDATE `description` = VALUES(`description`);

-- Resolve reference IDs into session variables
SET @admin_id := (SELECT user_id FROM users WHERE username = 'admin' LIMIT 1);
SET @staff_id := (SELECT user_id FROM users WHERE username = 'ict_staff' LIMIT 1);
SET @off_officeofthemayor := (SELECT office_id FROM offices WHERE office_name = 'Office of the Mayor' LIMIT 1);
SET @off_officeofthevicemayor := (SELECT office_id FROM offices WHERE office_name = 'Office of the Vice Mayor' LIMIT 1);
SET @off_sangguniangbayanoffi := (SELECT office_id FROM offices WHERE office_name = 'Sangguniang Bayan Office' LIMIT 1);
SET @off_humanresourcemanagem := (SELECT office_id FROM offices WHERE office_name = 'Human Resource Management Office' LIMIT 1);
SET @off_budgetoffice := (SELECT office_id FROM offices WHERE office_name = 'Budget Office' LIMIT 1);
SET @off_accountingoffice := (SELECT office_id FROM offices WHERE office_name = 'Accounting Office' LIMIT 1);
SET @off_treasuryoffice := (SELECT office_id FROM offices WHERE office_name = 'Treasury Office' LIMIT 1);
SET @off_assessorsoffice := (SELECT office_id FROM offices WHERE office_name = 'Assessor\'s Office' LIMIT 1);
SET @off_civilregistrarsoffic := (SELECT office_id FROM offices WHERE office_name = 'Civil Registrar\'s Office' LIMIT 1);
SET @off_municipalengineering := (SELECT office_id FROM offices WHERE office_name = 'Municipal Engineering Office' LIMIT 1);
SET @off_municipalplanningand := (SELECT office_id FROM offices WHERE office_name = 'Municipal Planning and Development Office' LIMIT 1);
SET @off_municipalhealthoffic := (SELECT office_id FROM offices WHERE office_name = 'Municipal Health Office' LIMIT 1);
SET @off_municipalsocialwelfa := (SELECT office_id FROM offices WHERE office_name = 'Municipal Social Welfare and Development Office' LIMIT 1);
SET @off_municipalagriculture := (SELECT office_id FROM offices WHERE office_name = 'Municipal Agriculture Office' LIMIT 1);
SET @off_generalservicesoffic := (SELECT office_id FROM offices WHERE office_name = 'General Services Office' LIMIT 1);
SET @off_informationandcommun := (SELECT office_id FROM offices WHERE office_name = 'Information and Communications Technology Office' LIMIT 1);
SET @off_disasterriskreductio := (SELECT office_id FROM offices WHERE office_name = 'Disaster Risk Reduction and Management Office' LIMIT 1);
SET @cat_appliances := (SELECT category_id FROM categories WHERE category_name = 'Appliances' LIMIT 1);
SET @cat_ictequipment := (SELECT category_id FROM categories WHERE category_name = 'ICT Equipment' LIMIT 1);
SET @cat_officefurniture := (SELECT category_id FROM categories WHERE category_name = 'Office Furniture' LIMIT 1);
SET @cat_officeequipment := (SELECT category_id FROM categories WHERE category_name = 'Office Equipment' LIMIT 1);
SET @cat_motorvehicle := (SELECT category_id FROM categories WHERE category_name = 'Motor Vehicle' LIMIT 1);
SET @cat_heavyequipment := (SELECT category_id FROM categories WHERE category_name = 'Heavy Equipment' LIMIT 1);
SET @cat_communicationequipme := (SELECT category_id FROM categories WHERE category_name = 'Communication Equipment' LIMIT 1);
SET @cat_medicalequipment := (SELECT category_id FROM categories WHERE category_name = 'Medical Equipment' LIMIT 1);
SET @cat_agriculturalequipmen := (SELECT category_id FROM categories WHERE category_name = 'Agricultural Equipment' LIMIT 1);
SET @cat_securityequipment := (SELECT category_id FROM categories WHERE category_name = 'Security Equipment' LIMIT 1);

-- Base asset_id: first auto-increment value this batch will receive.
-- Assumes this script runs uninterrupted with no concurrent writers
-- (true for a fresh dev/demo database load).
SET @base_asset_id := (SELECT `AUTO_INCREMENT` FROM information_schema.tables
    WHERE table_schema = DATABASE() AND table_name = 'assets');

